import{_ as i,o as e,c as l,ae as t}from"./chunks/framework.FQ5RHm_v.js";const c=JSON.parse('{"title":"wvke-sdk | Идеальная настройка!","titleTemplate":false,"description":"","frontmatter":{"title":"wvke-sdk | Идеальная настройка!","titleTemplate":false},"headers":[],"relativePath":"ru/index.md","filePath":"ru/index.md"}'),s={name:"ru/index.md"};function r(d,a,n,o,h,p){return e(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="wvke-sdk" tabindex="-1">wvke-sdk <a class="header-anchor" href="#wvke-sdk" aria-label="Permalink to &quot;wvke-sdk&quot;">​</a></h1><p>wvke-sdk — это JavaScript SDK для связи с игровыми периферийными устройствами, включая клавиатуры и мыши.</p><p>Построенный на современном стеке технологий WebHID, он обеспечивает глубокую настройку и интеллектуальное управление клавиатурами, мышами и другими периферийными устройствами. SDK ускоряет сквозную поставку игровых периферийных продуктов и открывает новые возможности в игровой экосистеме. Проект разрабатывается и поддерживается командой GDE Game Driver Engine Team.</p><h2 id="типы-sdk" tabindex="-1">Типы SDK <a class="header-anchor" href="#типы-sdk" aria-label="Permalink to &quot;Типы SDK&quot;">​</a></h2><h3 id="⌨️-линеиная-клавиатура" tabindex="-1">⌨️ Линейная клавиатура <a class="header-anchor" href="#⌨️-линеиная-клавиатура" aria-label="Permalink to &quot;⌨️ Линейная клавиатура&quot;">​</a></h3><p>Создана для механических клавиатур:</p><ul><li>Маппинг клавиш и переключение слоев</li><li>Управление RGB-подсветкой</li><li>Авторизация WebHID, список авторизованных устройств, инициализация</li><li>Переключатель полного хода RT, настройка хода и безопасной зоны</li><li>Запись и воспроизведение макросов</li><li>Регулировка частоты опроса (1KHz-8KHz)</li><li>Переключение режима системы (Windows/Mac)</li></ul><h3 id="🖱️-sdk-мыши" tabindex="-1">🖱️ SDK Мыши <a class="header-anchor" href="#🖱️-sdk-мыши" aria-label="Permalink to &quot;🖱️ SDK Мыши&quot;">​</a></h3><p>Создан для игровых мышей:</p><ul><li>Регулировка DPI (400-16000 DPI)</li><li>Программирование кнопок и макросы</li><li>Настройка RGB-подсветки</li><li>Регулировка высоты отрыва</li><li>Оптимизация опроса</li></ul><h2 id="возможности" tabindex="-1">Возможности <a class="header-anchor" href="#возможности" aria-label="Permalink to &quot;Возможности&quot;">​</a></h2><ul><li>Современная поддержка JavaScript/TypeScript</li><li>Аппаратная связь через WebHID</li><li>Полные API управления подсветкой</li><li>API маппинга клавиш и макросов</li><li>API хода RT, расширенных клавиш и инициализации</li><li>API DPI и маппинга кнопок мыши</li><li>Сервис пользовательского обновления</li><li>Детальная документация API</li></ul><h2 id="учебник" tabindex="-1">Учебник <a class="header-anchor" href="#учебник" aria-label="Permalink to &quot;Учебник&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wvke-sdk</span></span></code></pre></div><p>Подробнее см. в <a href="/wvke.sdkdoc/docs/ru/api/info.html">документации API</a>.</p>',15)])])}const u=i(s,[["render",r]]);export{c as __pageData,u as default};
